   "Descrição do gráfico: A força de atrito é constante em um valor diferente de zero. (Fim da descrição)",
   "Descrição do gráfico: A força de atrito inicia em um valor constante diferente de zero e diminui linearmente a partir de um certo tempo. (Fim da descrição)",
   "Descrição do gráfico: A força de atrito inicia em um valor diferente de zero, aumenta linearmente e diminui linearmente. (Fim da descrição)"
