  "enunciado": "A dimetilamina é uma substância de elevada toxidez que entra em ebulição a 7 graus Celsius. Na madrugada de um dia frio, essa substância se espalhou por uma rodovia após um acidente de trânsito envolvendo um caminhão que transportava esse produto. Para minimizar a agressão ao meio ambiente, bem como evitar a evaporação da dimetilamina com a elevação da temperatura ao longo do dia, um químico considerou o uso de algumas substâncias ou misturas como água, vinagre, óleo de soja, sal de cozinha e bicarbonato de sódio.\n\nDentre as opções apresentadas, o tratamento correto para minimizar esse problema é usar",
  "alternativas": [
   "água.",
   "vinagre.",
   "óleo de soja.",
   "sal de cozinha.",
   "bicarbonato de sódio."
  ],
