  "enunciado": "A laje de um depósito de bebidas tem 50 metros quadrados de área útil de armazenamento e foi projetada para suportar pressões de até 10 elevado a quatro pascals. O gerente do estabelecimento pretende armazenar um produto cuja densidade é 1250 quilogramas por metro cúbico. Considere a aceleração da gravidade igual a 10 metros por segundo ao quadrado.\n\nA altura máxima, em metro, de empilhamento do produto que essa laje é capaz de suportar é",
