  "enunciado": "Os funcionários de um zoológico observaram um aumento na taxa de mortalidade de aves aquáticas por afogamento. Um grupo de biólogos analisou o comportamento das aves por várias semanas e observou que elas apresentavam dificuldade de flutuação, por causa do encharcamento das penas com água.\n\nO aumento na taxa de mortalidade dessas aves estava associado a uma redução na",
  "alternativas": [
   "dilatação do papo.",
   "reposição de penas das asas.",
   "secreção da glândula uropigial.",
   "formação da membrana natatória.",
   "largura das cavidades de ossos pneumáticos."
  ],
