  "enunciado": "Uma escola de idiomas oferece cursos de inglês, espanhol, francês e alemão. Os gráficos apresentam a distribuição percentual das matrículas, por idioma, em 2023, e a distribuição da quantidade de matrículas, por idioma, em 2024.\n\nDescrição dos gráficos: Um gráfico de setores, intitulado Porcentagem de matrículas por idioma - 2023, apresenta os seguintes dados:\nInglês: 60 por cento;\nEspanhol: 25 por cento;\nFrancês: 10 por cento;\nAlemão: 5 por cento.\nUm outro gráfico de barras verticais, intitulado Quantidade de matrículas por idioma - 2024, apresenta os seguintes dados:\nInglês: 280;\nEspanhol: 80;\nFrancês: 20;\nAlemão: 20.\n(Fim da descrição)\n\nPara planejar as atividades de 2025, o gerente da escola estimou que o total de matrículas será o mesmo de 2024, e a distribuição percentual das matrículas, por idioma, será igual à registrada em 2023.\n\nSegundo essa estimativa, o número de matrículas no curso de francês para o ano de 2025 será",
