  "enunciado": "Os quadrados em cinza na figura representam os quarteirões de uma parte do bairro onde moram João e seu amigo. O quadrado pequeno (A), pintado em preto e localizado no canto superior esquerdo de um quadrado maior, indica a casa do amigo de João. João também mora em uma casa de esquina, mas na extremidade nordeste de um quarteirão. Para chegar à casa de seu amigo, ao sair de casa, João deve caminhar pelo quarteirão onde mora na direção oeste, dobrar à direita, caminhar por três quarteirões na direção norte e dobrar à esquerda. A casa de seu amigo fica no segundo quarteirão a oeste.\n\nDescrição da figura: A figura é composta por 42 quadrados, distribuídos em 7 linhas e 6 colunas, e pela representação da rosa dos ventos indicando a direção Norte para cima, a direção Sul para baixo, a direção Oeste para a esquerda e a direção Leste para a direita. Alguns desses quadrados estão marcados por uma letra, na seguinte configuração:\nQuadrado na linha 1 e coluna 5: letra Q;\nQuadrado na linha 4 e coluna 5: letra S;\nQuadrado na linha 7 e coluna 1: letra R;\nQuadrado na linha 7 e coluna 5: letra P;\nQuadrado na linha 7 e coluna 6: letra T.\nO quadrado pequeno com a letra A, pintado em preto, está no canto superior esquerdo do quadrado localizado na linha 4 e coluna 3.\n(Fim da descrição)\n\nO quarteirão onde se encontra a casa de João é representado pelo quadrado com a letra",
