  "enunciado": "Uma caixa de descarga, acoplada a um vaso sanitário, tem a forma de paralelepípedo reto retângulo cujas dimensões internas da base são 2,5 decímetros e 1,5 decímetro. Nessa caixa há uma boia que interrompe o abastecimento quando a altura da coluna de água atinge 2 decímetros, conforme a figura.\n\nDescrição da figura: A primeira figura apresenta a caixa de descarga, em formato de paralelepípedo reto retângulo, cujas medidas da base são 2,5 decímetros e 1,5 decímetro, sendo enchida de água. A segunda figura apresenta a mesma caixa, com uma boia interrompendo o abastecimento de água e uma coluna de água, em seu interior, com 2 decímetros de altura.\n\nA cada acionamento da descarga, todo o volume de água contida na caixa é despejado no vaso. Para reduzir o volume de água despejado a cada acionamento, uma pessoa colocará, no interior dessa caixa, garrafas de 300 mililitros, cheias de areia e tampadas, de modo a ficarem submersas quando o abastecimento for interrompido.\nPara garantir o funcionamento eficiente, o mínimo de água despejada a cada acionamento deve ser de 5 litros.\n\nA quantidade máxima de garrafas que serão colocadas nessa caixa, garantindo um funcionamento eficiente, é igual a",
