  "prova": {
   "banca": "INEP",
   "ano": 2024,
   "orgao": "ENEM, 2º dia, questão 92"
  },
  "enunciado": "O exoesqueleto dos crustáceos é formado por quitina e impregnações de sais calcários e, por isso, é mais duro quando comparado com o exoesqueleto de outros artrópodes. Esse revestimento externo confere proteção, mas, por ser duro, limita o crescimento desses animais.\n\nPara superar essa limitação, o exoesqueleto deve ser",
  "alternativas": [
   "formado somente na fase adulta do animal.",
   "fragmentado para expansão nas áreas de articulação.",
   "modelado continuamente para ajuste ao tamanho do corpo.",
   "substituído por meio de mudas que ocorrem periodicamente.",
   "impregnado por pequena quantidade de sais para sua distensão."
  ],
  "resposta": 3,
