  "enunciado": "Uma ambulância em alta velocidade com a sirene ligada desloca-se em direção a um radar operado por uma pessoa. O radar emite ondas de rádio com frequência f zero que são refletidas pela dianteira da ambulância, retornando para o detector com frequência fr. A percepção do operador do radar, em relação ao som emitido pela sirene, é de que este se altera à medida que a ambulância se aproxima ou se afasta.\n\nDurante a aproximação, como o operador percebe o som da sirene e qual é a relação entre as frequências fr e f zero medidas pelo radar?",
  "alternativas": [
   "Mais grave do que o som emitido e fr menor que f zero.",
   "Mais agudo do que o som emitido e fr menor que f zero.",
   "Mais agudo do que o som emitido e fr igual a f zero.",
   "Mais agudo do que o som emitido e fr maior que f zero.",
   "Mais grave do que o som emitido e fr maior que f zero."
  ],
  "resposta": 3,
