  "enunciado": "Uma empresa produz mochilas escolares sob encomenda. Essa empresa tem um custo total de produção composto por um custo fixo, que não depende do número de mochilas, mais um custo variável, que é proporcional ao número de mochilas produzidas. O custo total cresce de forma linear, e a tabela apresenta esse custo para três quantidades de mochilas produzidas.\n\nDescrição da tabela: Tabela, que apresenta o custo total em relação a algumas quantidades de mochilas, apresentando os seguintes dados: 30 mochilas custam 1050 reais, 50 mochilas custam 1650 reais e 100 mochilas custam 3150 reais. (Fim da descrição)\n\nO custo total, em real, para a produção de 80 mochilas será",
