  "enunciado": "A umidade relativa do ar é um dos indicadores utilizados na meteorologia para fazer previsões sobre o clima. O quadro apresenta as médias mensais, em porcentagem, da umidade relativa do ar em um período de seis meses consecutivos em uma cidade.\n\nDescrição do quadro: Quadro que apresenta a média mensal da umidade relativa do ar, em porcentagem, associada a alguns meses, apresentando os seguintes dados:\nmaio: 66,\njunho: 64,\njulho: 54,\nagosto: 46,\nsetembro: 60 e\noutubro: 64.\n(Fim da descrição)\n\nNessa cidade, a mediana desses dados, em porcentagem, da umidade relativa do ar no período considerado foi",
