  "prova": {
   "banca": "INEP",
   "ano": 2024,
   "orgao": "ENEM, 2º dia, questão 167"
  },
  "enunciado": "Uma empresa tem 400 funcionários, distribuídos em três setores: administrativo, logística e produção. O gráfico apresenta a distribuição quantitativa desses funcionários, por setor e por faixa etária.\n\nDescrição do gráfico: Gráfico de colunas, que representa a quantidade de funcionários que trabalham nos setores administrativo, logística e produção, e indica a porcentagem desses funcionários, por faixa etária, em cada um desses setores.\nO setor administrativo tem 80 funcionários, sendo 20 por cento com idades até 25 anos, 30 por cento com idades entre 25 e 45 anos, e 50 por cento com idades a partir de 45 anos.\nO setor logística tem 120 funcionários, sendo 25 por cento com idades até 25 anos, 40 por cento com idades entre 25 e 45 anos, e 35 por cento com idades a partir de 45 anos.\nO setor produção tem 200 funcionários, sendo 40 por cento com idades até 25 anos, 35 por cento com idades entre 25 e 45 anos, e 25 por cento com idades a partir de 45 anos.\n(Fim da descrição)\n\nUma viagem de férias será sorteada entre esses funcionários, de forma que todos terão igual probabilidade de serem sorteados.\n\nA maior probabilidade é que o funcionário sorteado esteja na faixa etária",
  "alternativas": [
   "entre 25 e 45 anos, pois é a faixa etária com maior quantidade de funcionários.",
   "entre 25 e 45 anos, pois é a única faixa etária cujas porcentagens são maiores do que as porcentagens mínimas de cada setor.",
   "até 25 anos, pois é a única faixa etária cujos percentuais associados aos setores aumentam com o aumento da quantidade de funcionários por setor.",
   "até 25 anos, pois é a faixa etária que apresenta maior quantidade de funcionários no setor de produção, que é o setor que emprega metade dos funcionários dessa empresa.",
   "a partir de 45 anos, pois a soma das porcentagens associadas a essa faixa etária é 110 por cento, que é maior do que as respectivas somas associadas às outras faixas etárias, que são 105 por cento e 85 por cento."
  ],
  "resposta": 0,
