  "enunciado": "A prefeitura de uma cidade planeja construir três postos de saúde. Esses postos devem ser construídos em locais equidistantes entre si e de forma que as distâncias desses três postos ao hospital dessa cidade sejam iguais. Foram conseguidos três locais para a construção dos postos de saúde que apresentam as características desejadas, e que distam 10 quilômetros entre si, conforme o esquema, no qual o ponto H representa o local onde está construído o hospital; os pontos P índice 1, P índice 2 e P índice 3, os postos de saúde; e esses quatro pontos estão em um mesmo plano.\n\nDescrição da figura: Figura apresenta 4 pontos: P índice 1, acima ao centro; P índice 2, abaixo à direita; P índice 3, abaixo à esquerda; e H, entre esses pontos, na seguinte configuração: a distância de P índice 1 a P índice 2, de P índice 2 a P índice 3, e de P índice 3 a P índice 1 é de 10 quilômetros. As distâncias de H a cada um desses pontos têm a mesma medida. (Fim da descrição)\n\nA distância, em quilômetro, entre o hospital e cada um dos postos de saúde, é um valor entre",
