  "enunciado": "Em uma indústria, o controle da dureza da água é importante quando ela é utilizada em caldeiras, uma vez que sais pouco solúveis, formados a partir de sulfatos e carbonatos, podem acumular-se no interior das tubulações, causando obstruções. Para avaliar a água utilizada nessa indústria, foram realizados testes de qualidade que consideraram os parâmetros apresentados no quadro.\n\nDescrição do quadro: O quadro indica os parâmetros medidos para testes de 1 a 5:\nTeste 1: cálcio;\nTeste 2: cloreto;\nTeste 3: turbidez;\nTeste 4: coliformes totais;\nTeste 5: sólidos sedimentáveis.\n(Fim da descrição)\n\nQual teste deve ser considerado para controlar a formação desse tipo de obstrução de tubulações?",
