  "enunciado": "As aves apresentam dois tipos de músculos em seus corpos: vermelhos e brancos. Aves migratórias como garças, gansos e patos selvagens têm os músculos vermelhos bem desenvolvidos, com ampla rede de vasos sanguíneos.\n\nNas viagens por grandes distâncias, tais músculos são fundamentais, pois favorecem o(a)",
