  "enunciado": "Um supermercado conta com cinco caixas disponíveis para pagamento. Foram instaladas telas que apresentam o tempo médio gasto por cada caixa para iniciar e finalizar o atendimento de cada cliente, e o número de pessoas presentes na fila de cada caixa em tempo real. Um cliente, na hora de passar sua compra, sabendo que cada um dos cinco caixas iniciará um novo atendimento naquele momento, pretende gastar o menor tempo possível de espera na fila. Ele observa que as telas apresentavam as informações a seguir.\n\nCaixa 1: atendimento 12 minutos, 5 pessoas na fila.\nCaixa 2: atendimento 6 minutos, 9 pessoas na fila.\nCaixa 3: atendimento 5 minutos, 6 pessoas na fila.\nCaixa 4: atendimento 15 minutos, 2 pessoas na fila.\nCaixa 5: atendimento 9 minutos, 3 pessoas na fila.\n\nPara alcançar seu objetivo, o cliente deverá escolher o caixa",
