  "enunciado": "Uma loja vende seus produtos de duas formas: à vista ou financiado em três parcelas mensais iguais. Para definir o valor dessas parcelas nas vendas financiadas, a loja aumenta em 20 por cento o valor do produto à vista e divide esse novo valor por 3. A primeira parcela deve ser paga no ato da compra, e as duas últimas, em 30 e 60 dias após a compra.\nUm cliente da loja decidiu comprar, de forma financiada, um produto cujo valor à vista é 1500 reais.\nUtilize 5,29 como aproximação para raiz quadrada de 28.\n\nA taxa mensal de juros compostos praticada nesse financiamento é de",
